# Lost Astronaut 2 - reference solution
# DP over (position, characters remaining) with a bitmask of reachable checksums.
import sys

def build_table():
    enc = {}
    for c in list(range(65, 91)) + list(range(97, 123)) + [32]:
        for tok in (bin(c)[2:], oct(c)[2:], format(c, 'x'), chr(c)):
            enc.setdefault(tok, set()).add(c)
    return {k: sorted(v) for k, v in enc.items()}

ENC = build_table()

def options(s):
    L = len(s)
    return [[(l, o) for l in range(1, 8) if i + l <= L and s[i:i+l] in ENC
             for o in ENC[s[i:i+l]]] for i in range(L)]

def tables(s, n, ck):
    L = len(s)
    opts = options(s)
    # fwd[i]: bitmask of how many characters can be decoded from s[:i]
    fwd = [0] * (L + 1)
    fwd[0] = 1
    full = (1 << (n + 1)) - 1
    for i in range(L):
        if fwd[i]:
            for l, _ in opts[i]:
                fwd[i + l] |= (fwd[i] << 1) & full
    # back[i][r]: bitmask of checksums reachable decoding s[i:] into exactly r chars
    cap = (1 << (ck + 1)) - 1
    back = [None] * (L + 1)
    back[L] = {0: 1}
    for i in range(L - 1, -1, -1):
        d = {}
        allowed = fwd[i]
        for l, o in opts[i]:
            for r, m in back[i + l].items():
                r1 = r + 1
                if r1 <= n and (allowed >> (n - r1)) & 1:
                    v = (m << o) & cap
                    if v:
                        d[r1] = d.get(r1, 0) | v
        back[i] = d
    return opts, back

def solve(s, n, ck):
    opts, back = tables(s, n, ck)
    if not (back[0].get(n, 0) >> ck) & 1:
        return None
    out, i, r, x = [], 0, n, ck
    while i < len(s):
        for l, o in opts[i]:
            if x >= o and (back[i + l].get(r - 1, 0) >> (x - o)) & 1:
                out.append(chr(o)); i += l; r -= 1; x -= o
                break
    return ''.join(out)

if __name__ == '__main__':
    n = int(input())
    ck = int(input())
    stream = input().rstrip('\n')
    print(solve(stream, n, ck))
